{
  "summary": "The agreement includes a franchise fee arrangement where the grantee pays a percentage share based on the total dollar value of gas sales, increased annually.",
  "evidence": [
    {
      "passage_id": 1,
      "quote": "Grantor's Franchise Fee shall be a percentage share of the base year total annual Franchise Fee, which shall be determined on a pro rata basis according to its percentage share of the total dollar value of Grantee's gas sales occurring within the localities during the calendar year."
    },
    {
      "passage_id": 2,
      "quote": "(b) For each succeeding calendar year during the term of this Franchise, the total annual Franchise Fee paid by Grantee to the localities shall be the base year total annual Franchise Fee increased by three (3) percent compounded annually over the term of the Franchise."
    }
  ]
}
